mutation SetAutoDeploy($id: String!, $enabled: Boolean!) {
  setAutoDeploy(id: $id, enabled: $enabled) {
    id
    autoDeploy
    __typename
  }
}

mutation SetBuildCommand($id: String!, $command: String!, $confirm: String) {
  setBuildCommand(id: $id, command: $command, confirm: $confirm) {
    id
    buildCommand
    phase
    __typename
  }
}

mutation DeleteService($id: String!, $confirm: String) {
  deleteService(id: $id, confirm: $confirm)
}
